mapper.select:
select user_id, article_id, last_reading_time
from user_reading_history
where
    user_id=#{userId}
  and (#{lastReadingTime} is null
    or last_reading_time < #{lastReadingTime}
    or (last_reading_time=#{lastReadingTime} and article_id < #{lastId}))
order by last_reading_time desc , article_id desc
limit #{size}
